<?= $this->extend('site/layout') ?><?= $this->section('content') ?>
<?php $image = $kind === 'service' ? 'assets/images/BRZ_2919.jpg' : ($kind === 'project' ? 'assets/images/banner1.jpg' : 'assets/images/palm-plantation.jpg'); $prefix = $kind === 'service' ? 'services/' : ($kind === 'project' ? 'projects/' : 'news/'); ?>
<section class="inner-hero-ref" style="background-image:linear-gradient(180deg,rgba(9,28,20,.55),rgba(9,28,20,.35) 40%,rgba(9,28,20,.9)),url('<?= base_url($image) ?>')"><div><div class="crumbs"><a href="<?= site_url('/') ?>">Home</a><span><?= esc($eyebrow) ?></span></div><p class="mono lime"><?= esc($eyebrow) ?></p><h1><?= esc($title) ?></h1><p><?= esc($intro) ?></p></div></section>
<?php if ($kind === 'service'): ?>
