<?php else: ?>
<section class="reference-cards news-reference"><?php if ($items): $featured = array_shift($items); ?><a class="reference-featured" href="<?= site_url($prefix . $featured['slug']) ?>"><img src="<?= base_url($featured['cover_image']) ?>" alt=""><div><p class="mono">LATEST · COMPANY · <?= esc(date('d M Y', strtotime($featured['published_at']))) ?></p><h2><?= esc($featured['title']) ?></h2><p><?= esc($featured['excerpt']) ?></p><b>Read article →</b></div></a><?php endif ?><div class="reference-filters" aria-label="Filter news"><?php foreach (['All','Company','Operations','Nursery'] as $filter): ?><button type="button" data-filter="<?= esc($filter) ?>" class="<?= $filter === 'All' ? 'active' : '' ?>"><?= esc($filter) ?></button><?php endforeach ?></div><div class="reference-card-grid"><?php foreach ($items as $item): ?><?php $newsCategory = str_contains($item['slug'], 'seedling') || str_contains($item['slug'], 'planting') ? 'Nursery' : (str_contains($item['slug'], 'quality-control') || str_contains($item['slug'], 'fresh-fruit') ? 'Operations' : 'Company'); ?><a class="reference-news-card" data-category="<?= esc($newsCategory) ?>" href="<?= site_url($prefix . $item['slug']) ?>"><img src="<?= base_url($item['cover_image']) ?>" alt=""><p class="mono"><?= esc(strtoupper($newsCategory)) ?> · <?= esc(date('d M Y', strtotime($item['published_at']))) ?></p><h2><?= esc($item['title']) ?></h2><p><?= esc($item['excerpt']) ?></p></a><?php endforeach ?></div></section>
<?php endif ?>
<script>document.querySelectorAll('[data-filter]').forEach(button => button.addEventListener('click', () => { document.querySelectorAll('[data-filter]').forEach(b => b.classList.remove('active')); button.classList.add('active'); document.querySelectorAll('[data-category]').forEach(card => card.hidden = button.dataset.filter !== 'All' && card.dataset.category !== button.dataset.filter); }));</script>
